window.docContents[40].resolve({"/StlcProp/#Type-Systems--StlcProp___-Properties-of-STLC--Preservation--Main-Theorem":{"contents":"We now have the ingredients we need to prove preservation: if a\nclosed, well-typed term t has type τ and takes a step to t',\nthen t' is also a closed term with type τ.  In other words,\nthe small-step reduction relation preserves types.\n\ntheorem preservation (t t' : Tm) (τ : Ty)\n    (hτ : <{ ∅ ⊢ ~t ⦂ ~τ }>) (hs : t ⟶ t') : <{ ∅ ⊢ ~t' ⦂ ~τ }> := by\n  generalize hΓ : (∅ : Context) = Γ at hτ\n  induction hτ generalizing t' with\n  | var => cases hs\n  | abs => cases hs\n  | tru => cases hs\n  | fls => cases hs\n  | app Γ τ₁ τ₂ t₁ t₂ h₁ h₂ ih₁ ih₂ =>\n    subst hΓ\n    cases hs with\n    | appAbs _ _ _ _ _ =>\n      -- The one interesting case: the desired result is the substitution lemma.\n      cases h₁ with\n      | abs _ _ _ _ _ hb =>\n        apply substitution_preserves_typing\n        · exact hb\n        · exact h₂\n    | app1 _ t₁' _ h =>\n      constructor\n      · apply ih₁\n        · exact h\n        · rfl\n      · exact h₂\n    | app2 _ _ t₂' _ h =>\n      constructor\n      · exact h₁\n      · apply ih₂\n        · exact h\n        · rfl\n  | ite Γ t₁ t₂ t₃ τ₁ h₁ h₂ h₃ ih₁ ih₂ ih₃ =>\n    subst hΓ\n    cases hs with\n    | ifTrue => exact h₂\n    | ifFalse => exact h₃\n    | ifStep _ t₁' _ _ h =>\n      constructor\n      · apply ih₁\n        · exact h\n        · rfl\n      · exact h₂\n      · exact h₃\n\n\n\n\n\n\n","context":"Type Systems\u0009StlcProp: Properties of STLC\u0009Preservation","header":"6.3.3. Main Theorem","id":"/StlcProp/#Type-Systems--StlcProp___-Properties-of-STLC--Preservation--Main-Theorem"}});